// EmitDeleteFinalFields emits fields for DeletedNode.FinalFields
// (sMD_Always | sMD_DeleteFinal), including PreviousTxn* which are
// otherwise hidden.
func (a *AccountRoot) EmitDeleteFinalFields(out map[string]any) {
	a.emitAll(out, false)
	if a.present&accountrootBitPreviousTxnID != 0 {
		out["PreviousTxnID"] = a.PreviousTxnID
	}
	if a.present&accountrootBitPreviousTxnLgrSeq != 0 {
		out["PreviousTxnLgrSeq"] = a.PreviousTxnLgrSeq
	}
}

func (a *AccountRoot) EmitDeletePreviousFields(prev Entry, out map[string]any) {
	a.EmitPreviousFields(prev, out)
}

// PreviousTxn returns the threading values from the receiver. Empty id /
// zero seq mean the corresponding field is absent.
func (a *AccountRoot) PreviousTxn() (string, uint32) {
	var id string
	var seq uint32
	if a.present&accountrootBitPreviousTxnID != 0 {
		id = a.PreviousTxnID
	}
	if a.present&accountrootBitPreviousTxnLgrSeq != 0 {
		seq = a.PreviousTxnLgrSeq
	}
	return id, seq
}

